using System;using System.Collections.Generic;using System.Linq;using Avalonia;using Avalonia.Controls;using Avalonia.Layout;using Avalonia.Media;using Kreta.Core;using Kreta.Contexts;namespace Kreta.Dynamic;public class ClassGradeEntryPanel_d4fefcc863a3442785f644d8aa17b8e3 : UserControl, IEvolView{    public string Name => "Osztályszintű dolgozat rögzítése";    public string Description => "Panel új jegyek rögzítésére egy osztály számára.";    private readonly ITeacherContext? _context;    private ComboBox _studentComboBox;    private ComboBox _subjectComboBox;    private NumericUpDown _gradeInput;    private TextBlock _statusTextBlock;    public ClassGradeEntryPanel_d4fefcc863a3442785f644d8aa17b8e3()    {    }    public ClassGradeEntryPanel_d4fefcc863a3442785f644d8aa17b8e3(ITeacherContext context)    {        _context = context;    }    public Control CreateView()    {        var grid = new Grid        {            Margin = new Thickness(20),            ColumnDefinitions = new ColumnDefinitions("Auto,*"),            RowDefinitions = new RowDefinitions("Auto,Auto,Auto,Auto,Auto")        };        var title = new TextBlock        {            Text = "Új dolgozatjegy rögzítése",            FontSize = 20,            FontWeight = FontWeight.Bold,            Margin = new Thickness(0, 0, 0, 20)        };        Grid.SetColumnSpan(title, 2);        grid.Children.Add(title);        var studentLabel = new TextBlock { Text = "Tanuló:", VerticalAlignment = VerticalAlignment.Center };        _studentComboBox = new ComboBox { Margin = new Thickness(10, 5) };        Grid.SetRow(studentLabel, 1);        Grid.SetRow(_studentComboBox, 1);        Grid.SetColumn(_studentComboBox, 1);        grid.Children.Add(studentLabel);        grid.Children.Add(_studentComboBox);        var subjectLabel = new TextBlock { Text = "Tantárgy:", VerticalAlignment = VerticalAlignment.Center };        _subjectComboBox = new ComboBox { Margin = new Thickness(10, 5) };        Grid.SetRow(subjectLabel, 2);        Grid.SetRow(_subjectComboBox, 2);        Grid.SetColumn(_subjectComboBox, 1);        grid.Children.Add(subjectLabel);        grid.Children.Add(_subjectComboBox);        var gradeLabel = new TextBlock { Text = "Érdemjegy:", VerticalAlignment = VerticalAlignment.Center };        _gradeInput = new NumericUpDown        {            Minimum = 1,            Maximum = 5,            Value = 5,            Margin = new Thickness(10, 5)        };        Grid.SetRow(gradeLabel, 3);        Grid.SetRow(_gradeInput, 3);        Grid.SetColumn(_gradeInput, 1);        grid.Children.Add(gradeLabel);        grid.Children.Add(_gradeInput);        var buttonPanel = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 10, Margin = new Thickness(0, 20, 0, 0) };        var saveButton = new Button { Content = "Jegy rögzítése" };        saveButton.Click += SaveButton_Click;        _statusTextBlock = new TextBlock { VerticalAlignment = VerticalAlignment.Center, FontWeight = FontWeight.Bold };        buttonPanel.Children.Add(saveButton);        buttonPanel.Children.Add(_statusTextBlock);        Grid.SetRow(buttonPanel, 4);        Grid.SetColumn(buttonPanel, 1);        grid.Children.Add(buttonPanel);        LoadInitialData();        return new Border { Padding = new Thickness(10), Child = grid };    }    private void LoadInitialData()    {        if (_context == null) return;        var students = _context.GetMyClassStudents()?.Where(u => u.Role == Role.Student).ToList();        _studentComboBox.ItemsSource = students;        _studentComboBox.DisplayMemberBinding = new Avalonia.Data.Binding("Name");        var subjects = _context.GetAllSubjects();        _subjectComboBox.ItemsSource = subjects;        _subjectComboBox.DisplayMemberBinding = new Avalonia.Data.Binding("Name");    }    private void SaveButton_Click(object? sender, Avalonia.Interactivity.RoutedEventArgs e)    {        if (_context == null)        {            _statusTextBlock.Text = "Hiba: Kontextus nem elérhető.";            _statusTextBlock.Foreground = Brushes.Red;            return;        }        var selectedStudent = _studentComboBox.SelectedItem as User;        if (selectedStudent == null)        {            _statusTextBlock.Text = "Kérlek válassz tanulót!";            _statusTextBlock.Foreground = Brushes.Red;            return;        }        var selectedSubject = _subjectComboBox.SelectedItem as Subject;        if (selectedSubject == null)        {            _statusTextBlock.Text = "Kérlek válassz tantárgyat!";            _statusTextBlock.Foreground = Brushes.Red;            return;        }        var gradeValue = (int)(_gradeInput.Value ?? 1);        var newGrade = new Grade        {            StudentId = selectedStudent.Id,            SubjectId = selectedSubject.Id,            Value = gradeValue,            Date = DateTime.Now        };        try        {            _context.AddGrade(selectedStudent.Id, newGrade);            _statusTextBlock.Text = $"{selectedStudent.Name} jegye ({gradeValue}) sikeresen rögzítve.";            _statusTextBlock.Foreground = Brushes.Green;        }        catch (Exception ex)        {            _statusTextBlock.Text = $"Hiba történt a mentés során: {ex.Message}";            _statusTextBlock.Foreground = Brushes.Red;        }    }}